mapper.select:
SELECT ser.series_id, ser.category_id, category.category_name, ser.series_name, ser.series_image, ser.series_description, ser.is_spiritpower, ser.is_hot, ser.is_avoid, ser.is_popular_new, ser.is_hot_recommend, ser.price, ser.price_ranges, ser.created_by, ser.created_time, ser.updated_by, ser.updated_time FROM product_series as ser inner join product_category as category on category.category_id = ser.category_id
AND series_id = #{seriesId}
AND series_name = #{seriesName}
AND is_hot = #{isHot}
AND is_avoid = #{isAvoid}
AND is_popular_new = #{isPopularNew}
AND is_hot_recommend = #{isHotRecommend}
AND is_spiritpower = #{isSpiritPower}
AND is_on_sale = #{isOnSale}
ORDER BY series_id
